import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const PORT = process.env.PORT ? Number(process.env.PORT) : 3000;

const CANDIDATE_FILES = [
  path.join(__dirname, "data", "books.json"),
  path.join(__dirname, "books.json"),
  path.join(__dirname, "data.json"),
];

const PRIMARY_FILE = CANDIDATE_FILES[0];

function ensureDataFile() {
  try {
    fs.mkdirSync(path.dirname(PRIMARY_FILE), { recursive: true });
    for (const f of CANDIDATE_FILES) {
      try {
        fs.mkdirSync(path.dirname(f), { recursive: true });
      } catch {}
    }
    if (!fs.existsSync(PRIMARY_FILE)) {
      let existing = null;
      for (const f of CANDIDATE_FILES) {
        if (fs.existsSync(f)) {
          try {
            existing = fs.readFileSync(f, "utf8");
            JSON.parse(existing);
            fs.copyFileSync(f, PRIMARY_FILE);
            break;
          } catch {}
        }
      }
      if (!existing) {
        fs.writeFileSync(PRIMARY_FILE, "[]", "utf8");
      }
    }
    syncFiles();
  } catch {}
}

function syncFiles() {
  try {
    const data = fs.readFileSync(PRIMARY_FILE, "utf8");
    for (const f of CANDIDATE_FILES) {
      if (f === PRIMARY_FILE) continue;
      try {
        fs.mkdirSync(path.dirname(f), { recursive: true });
        fs.writeFileSync(f, data, "utf8");
      } catch {}
    }
  } catch {}
}

function loadBooks() {
  ensureDataFile();
  try {
    const raw = fs.readFileSync(PRIMARY_FILE, "utf8");
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && Array.isArray(parsed.books)) return parsed.books;
    return [];
  } catch {
    return [];
  }
}

function saveBooks(books) {
  ensureDataFile();
  const json = JSON.stringify(books, null, 2);
  fs.writeFileSync(PRIMARY_FILE, json, "utf8");
  syncFiles();
}

function escapeHtml(s) {
  return String(s ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
*{box-sizing:border-box;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
body{max-width:800px;margin:2rem auto;padding:0 1rem;color:#111;line-height:1.5}
h1,h2{margin:0.8em 0 0.4em}
header{border-bottom:1px solid #ddd;padding-bottom:1rem;margin-bottom:1.5rem}
a{color:#0b57d0}
form{border:1px solid #ddd;padding:1rem;border-radius:8px;background:#fafafa;margin-bottom:2rem}
label{display:block;margin:0.5rem 0 0.2rem;font-weight:600}
input,textarea{width:100%;padding:0.5rem;border:1px solid #ccc;border-radius:6px}
button{margin-top:0.8rem;padding:0.6rem 1rem;border:0;background:#0b57d0;color:#fff;border-radius:6px;cursor:pointer}
button:hover{opacity:0.9}
.card{border:1px solid #e0e0e0;border-radius:8px;padding:0.8rem 1rem;margin:0.6rem 0;background:#fff}
.card small{color:#666}
.sections{display:grid;gap:2rem}
@media(min-width:700px){.sections{grid-template-columns:1fr 1fr}}
.empty{color:#666;font-style:italic}
.actions form{border:none;padding:0;background:transparent;display:inline}
.actions button{padding:0.4rem 0.7rem;font-size:0.9rem}
</style>
</head>
<body>
<header>
<h1><a href="/" style="text-decoration:none;color:inherit">Book Tracker</a></h1>
</header>
${body}
</body>
</html>`;
}

function homePage(books) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books.filter((b) => b.status === "finished");

  const bookItem = (b) => `
    <div class="card">
      <a href="/books/${encodeURIComponent(b.id)}"><strong>${escapeHtml(b.title)}</strong></a>
      <div><small>by ${escapeHtml(b.author || "Unknown")}</small></div>
      ${b.notes ? `<p>${escapeHtml(b.notes)}</p>` : ""}
      <div class="actions">
        ${b.status !== "finished" ? `<form method="POST" action="/books/${encodeURIComponent(b.id)}/finish"><button type="submit">Mark as finished</button></form>` : `<small>✓ Finished</small>`}
      </div>
    </div>
  `;

  return layout(
    "My Books",
    `
    <h2>Add a book</h2>
    <form method="POST" action="/books">
      <label for="title">Title *</label>
      <input id="title" name="title" required placeholder="e.g. Dune">

      <label for="author">Author</label>
      <input id="author" name="author" placeholder="e.g. Frank Herbert">

      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" rows="3" placeholder="Your thoughts..."></textarea>

      <button type="submit">Add book</button>
    </form>

    <div class="sections">
      <section>
        <h2>Currently Reading</h2>
        ${reading.length ? reading.map(bookItem).join("") : `<p class="empty">No books currently reading.</p>`}
      </section>
      <section>
        <h2>Finished</h2>
        ${finished.length ? finished.map(bookItem).join("") : `<p class="empty">No finished books yet.</p>`}
      </section>
    </div>
    `
  );
}

function detailPage(book) {
  if (!book) return null;
  return layout(
    book.title,
    `
    <a href="/">← Back to list</a>
    <h2>${escapeHtml(book.title)}</h2>
    <p><strong>Author:</strong> ${escapeHtml(book.author || "Unknown")}</p>
    <p><strong>Status:</strong> ${escapeHtml(book.status)}</p>
    ${book.notes ? `<h3>Notes</h3><p>${escapeHtml(book.notes)}</p>` : `<p><em>No notes</em></p>`}
    <p><small>ID: ${escapeHtml(book.id)}</small></p>
    ${
      book.status !== "finished"
        ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish"><button type="submit">Mark as finished</button></form>`
        : `<p>✓ Finished</p>`
    }
    <p style="margin-top:1.5rem"><small>Share this page: <a href="/books/${encodeURIComponent(book.id)}">/books/${encodeURIComponent(book.id)}</a></small></p>
    `
  );
}

function parseBody(req) {
  return new Promise((resolve) => {
    let data = "";
    req.on("data", (chunk) => (data += chunk));
    req.on("end", () => {
      const ct = (req.headers["content-type"] || "").toLowerCase();
      if (ct.includes("application/json")) {
        try {
          resolve(JSON.parse(data || "{}"));
        } catch {
          resolve({});
        }
      } else if (ct.includes("application/x-www-form-urlencoded")) {
        resolve(Object.fromEntries(new URLSearchParams(data)));
      } else {
        if (data.trim().startsWith("{")) {
          try {
            resolve(JSON.parse(data));
            return;
          } catch {}
        }
        try {
          const parsed = Object.fromEntries(new URLSearchParams(data));
          if (Object.keys(parsed).length) resolve(parsed);
          else resolve({ raw: data });
        } catch {
          resolve({});
        }
      }
    });
  });
}

function wantsJson(req) {
  const accept = (req.headers.accept || "").toLowerCase();
  return accept.includes("application/json");
}

function send(res, status, body, headers = {}) {
  res.writeHead(status, headers);
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(302, { Location: location });
  res.end();
}

async function handler(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);
  const pathname = url.pathname;
  const method = req.method;

  if (method === "GET" && (pathname === "/" || pathname === "/index.html")) {
    const books = loadBooks();
    if (wantsJson(req)) {
      const reading = books.filter((b) => b.status !== "finished");
      const finished = books.filter((b) => b.status === "finished");
      send(res, 200, JSON.stringify({ reading, finished, books }), { "Content-Type": "application/json" });
      return;
    }
    send(res, 200, homePage(books), { "Content-Type": "text/html; charset=utf-8" });
    return;
  }

  if (method === "GET" && pathname === "/api/books") {
    const books = loadBooks();
    send(res, 200, JSON.stringify(books), { "Content-Type": "application/json" });
    return;
  }
  if (method === "GET" && pathname === "/books") {
    const books = loadBooks();
    if (wantsJson(req)) {
      send(res, 200, JSON.stringify(books), { "Content-Type": "application/json" });
    } else {
      redirect(res, "/");
    }
    return;
  }

  let m;
  if (method === "GET" && (m = pathname.match(/^\/books\/([^/]+)$/))) {
    const id = decodeURIComponent(m[1]);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      if (wantsJson(req)) send(res, 404, JSON.stringify({ error: "Not found" }), { "Content-Type": "application/json" });
      else send(res, 404, layout("Not found", `<h2>Book not found</h2><a href="/">Back</a>`), { "Content-Type": "text/html" });
      return;
    }
    if (wantsJson(req)) {
      send(res, 200, JSON.stringify(book), { "Content-Type": "application/json" });
    } else {
      send(res, 200, detailPage(book), { "Content-Type": "text/html; charset=utf-8" });
    }
    return;
  }

  if (method === "GET" && (m = pathname.match(/^\/book\/([^/]+)$/))) {
    const id = decodeURIComponent(m[1]);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      send(res, 404, layout("Not found", `<h2>Book not found</h2><a href="/">Back</a>`), { "Content-Type": "text/html" });
      return;
    }
    send(res, 200, detailPage(book), { "Content-Type": "text/html; charset=utf-8" });
    return;
  }

  if (method === "POST" && (pathname === "/books" || pathname === "/add" || pathname === "/api/books" || pathname === "/books.json")) {
    const body = await parseBody(req);
    const title = (body.title || body.name || "").toString().trim();
    const author = (body.author || body.writer || "").toString().trim();
    const notes = (body.notes || body.note || body.description || "").toString();
    if (!title) {
      if (wantsJson(req) || String(pathname).startsWith("/api")) {
        send(res, 400, JSON.stringify({ error: "Title is required" }), { "Content-Type": "application/json" });
        return;
      }
      send(res, 400, layout("Error", `<p>Title is required</p><a href="/">Back</a>`), { "Content-Type": "text/html" });
      return;
    }
    const books = loadBooks();
    const newBook = {
      id: body.id ? String(body.id) : crypto.randomUUID ? crypto.randomUUID() : String(Date.now()),
      title,
      author,
      notes,
      status: body.status === "finished" ? "finished" : "reading",
    };
    books.push(newBook);
    saveBooks(books);
    if (wantsJson(req) || String(pathname).startsWith("/api") || (req.headers["content-type"] || "").includes("application/json")) {
      send(res, 201, JSON.stringify(newBook), { "Content-Type": "application/json" });
    } else {
      redirect(res, "/");
    }
    return;
  }

  if (
    (method === "POST" || method === "PUT" || method === "PATCH") &&
    (m = pathname.match(/^\/books\/([^/]+)\/(finish|finished|complete|done)$/))
  ) {
    const id = decodeURIComponent(m[1]);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      send(res, 404, JSON.stringify({ error: "Not found" }), { "Content-Type": "application/json" });
      return;
    }
    book.status = "finished";
    saveBooks(books);
    if (wantsJson(req) || (req.headers["content-type"] || "").includes("application/json")) {
      send(res, 200, JSON.stringify(book), { "Content-Type": "application/json" });
    } else {
      const referer = req.headers.referer || "/";
      if (referer.includes(`/books/${id}`)) redirect(res, `/books/${encodeURIComponent(id)}`);
      else redirect(res, "/");
    }
    return;
  }

  if ((method === "POST" || method === "PUT" || method === "PATCH") && (m = pathname.match(/^\/books\/([^/]+)$/))) {
    const id = decodeURIComponent(m[1]);
    const body = await parseBody(req);
    if (body.status || body._method || body.action) {
      const books = loadBooks();
      const book = books.find((b) => String(b.id) === String(id));
      if (!book) {
        send(res, 404, JSON.stringify({ error: "Not found" }), { "Content-Type": "application/json" });
        return;
      }
      const newStatus = (body.status || body.action || "").toString().toLowerCase();
      if (["finished", "finish", "done", "complete"].includes(newStatus) || body._method === "finish") {
        book.status = "finished";
        saveBooks(books);
      } else if (body.title || body.author || body.notes) {
        if (body.title) book.title = body.title;
        if (body.author) book.author = body.author;
        if (body.notes) book.notes = body.notes;
        saveBooks(books);
      }
      if (wantsJson(req)) send(res, 200, JSON.stringify(book), { "Content-Type": "application/json" });
      else redirect(res, `/books/${encodeURIComponent(id)}`);
      return;
    }
  }

  if ((method === "POST" || method === "PUT" || method === "PATCH") && pathname.match(/^\/finish\/([^/]+)$/)) {
    const id = decodeURIComponent(pathname.split("/")[2]);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (book) {
      book.status = "finished";
      saveBooks(books);
    }
    if (wantsJson(req)) send(res, 200, JSON.stringify(book || { error: "Not found" }), { "Content-Type": "application/json" });
    else redirect(res, "/");
    return;
  }

  if (method === "PATCH" && (m = pathname.match(/^\/api\/books\/([^/]+)$/))) {
    const id = decodeURIComponent(m[1]);
    const body = await parseBody(req);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      send(res, 404, JSON.stringify({ error: "Not found" }), { "Content-Type": "application/json" });
      return;
    }
    if (body.status) book.status = body.status;
    if (body.title) book.title = body.title;
    if (body.author) book.author = body.author;
    if (body.notes) book.notes = body.notes;
    saveBooks(books);
    send(res, 200, JSON.stringify(book), { "Content-Type": "application/json" });
    return;
  }

  send(res, 404, layout("Not found", `<h2>404 Not found</h2><p>No route for ${escapeHtml(method)} ${escapeHtml(pathname)}</p><a href="/">Home</a>`), {
    "Content-Type": "text/html",
  });
}

const server = http.createServer(handler);

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  server.listen(PORT, () => {
    console.log(`Book tracker listening on http://localhost:${PORT}`);
  });
}

export { server, loadBooks, saveBooks, PRIMARY_FILE };

