async function handler(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);
  const pathname = url.pathname;
  const method = req.method;

  if (method === "GET" && (pathname === "/" || pathname === "/index.html")) {
    const books = loadBooks();
    if (wantsJson(req)) {
      const reading = books.filter((b) => b.status !== "finished");
      const finished = books.filter((b) => b.status === "finished");
      send(res, 200, JSON.stringify({ reading, finished, books }), { "Content-Type": "application/json" });
      return;
    }
    send(res, 200, homePage(books), { "Content-Type": "text/html; charset=utf-8" });
    return;
  }

  if (method === "GET" && pathname === "/api/books") {
    const books = loadBooks();
    send(res, 200, JSON.stringify(books), { "Content-Type": "application/json" });
    return;
  }
  if (method === "GET" && pathname === "/books") {
    const books = loadBooks();
    if (wantsJson(req)) {
      send(res, 200, JSON.stringify(books), { "Content-Type": "application/json" });
    } else {
      redirect(res, "/");
    }
    return;
  }

  let m;
  if (method === "GET" && (m = pathname.match(/^\/books\/([^/]+)$/))) {
    const id = decodeURIComponent(m[1]);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      if (wantsJson(req)) send(res, 404, JSON.stringify({ error: "Not found" }), { "Content-Type": "application/json" });
      else send(res, 404, layout("Not found", `<h2>Book not found</h2><a href="/">Back</a>`), { "Content-Type": "text/html" });
      return;
    }
    if (wantsJson(req)) {
      send(res, 200, JSON.stringify(book), { "Content-Type": "application/json" });
    } else {
      send(res, 200, detailPage(book), { "Content-Type": "text/html; charset=utf-8" });
    }
    return;
  }

  if (method === "GET" && (m = pathname.match(/^\/book\/([^/]+)$/))) {
    const id = decodeURIComponent(m[1]);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      send(res, 404, layout("Not found", `<h2>Book not found</h2><a href="/">Back</a>`), { "Content-Type": "text/html" });
      return;
    }
    send(res, 200, detailPage(book), { "Content-Type": "text/html; charset=utf-8" });
    return;
  }

  if (method === "POST" && (pathname === "/books" || pathname === "/add" || pathname === "/api/books" || pathname === "/books.json")) {
    const body = await parseBody(req);
    const title = (body.title || body.name || "").toString().trim();
    const author = (body.author || body.writer || "").toString().trim();
    const notes = (body.notes || body.note || body.description || "").toString();
    if (!title) {
      if (wantsJson(req) || String(pathname).startsWith("/api")) {
        send(res, 400, JSON.stringify({ error: "Title is required" }), { "Content-Type": "application/json" });
        return;
      }
      send(res, 400, layout("Error", `<p>Title is required</p><a href="/">Back</a>`), { "Content-Type": "text/html" });
      return;
    }
    const books = loadBooks();
    const newBook = {
      id: body.id ? String(body.id) : crypto.randomUUID ? crypto.randomUUID() : String(Date.now()),
      title,
      author,
      notes,
      status: body.status === "finished" ? "finished" : "reading",
    };
    books.push(newBook);
    saveBooks(books);
    if (wantsJson(req) || String(pathname).startsWith("/api") || (req.headers["content-type"] || "").includes("application/json")) {
      send(res, 201, JSON.stringify(newBook), { "Content-Type": "application/json" });
    } else {
      redirect(res, "/");
    }
    return;
  }

  if (
    (method === "POST" || method === "PUT" || method === "PATCH") &&
    (m = pathname.match(/^\/books\/([^/]+)\/(finish|finished|complete|done)$/))
  ) {
    const id = decodeURIComponent(m[1]);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      send(res, 404, JSON.stringify({ error: "Not found" }), { "Content-Type": "application/json" });
      return;
    }
    book.status = "finished";
    saveBooks(books);
    if (wantsJson(req) || (req.headers["content-type"] || "").includes("application/json")) {
      send(res, 200, JSON.stringify(book), { "Content-Type": "application/json" });
    } else {
      const referer = req.headers.referer || "/";
      if (referer.includes(`/books/${id}`)) redirect(res, `/books/${encodeURIComponent(id)}`);
      else redirect(res, "/");
    }
    return;
  }

  if ((method === "POST" || method === "PUT" || method === "PATCH") && (m = pathname.match(/^\/books\/([^/]+)$/))) {
    const id = decodeURIComponent(m[1]);
    const body = await parseBody(req);
    if (body.status || body._method || body.action) {
      const books = loadBooks();
      const book = books.find((b) => String(b.id) === String(id));
      if (!book) {
        send(res, 404, JSON.stringify({ error: "Not found" }), { "Content-Type": "application/json" });
        return;
      }
      const newStatus = (body.status || body.action || "").toString().toLowerCase();
      if (["finished", "finish", "done", "complete"].includes(newStatus) || body._method === "finish") {
        book.status = "finished";
        saveBooks(books);
      } else if (body.title || body.author || body.notes) {
        if (body.title) book.title = body.title;
        if (body.author) book.author = body.author;
        if (body.notes) book.notes = body.notes;
        saveBooks(books);
      }
      if (wantsJson(req)) send(res, 200, JSON.stringify(book), { "Content-Type": "application/json" });
      else redirect(res, `/books/${encodeURIComponent(id)}`);
      return;
    }
  }

  if ((method === "POST" || method === "PUT" || method === "PATCH") && pathname.match(/^\/finish\/([^/]+)$/)) {
    const id = decodeURIComponent(pathname.split("/")[2]);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (book) {
      book.status = "finished";
      saveBooks(books);
    }
    if (wantsJson(req)) send(res, 200, JSON.stringify(book || { error: "Not found" }), { "Content-Type": "application/json" });
    else redirect(res, "/");
    return;
  }

  if (method === "PATCH" && (m = pathname.match(/^\/api\/books\/([^/]+)$/))) {
    const id = decodeURIComponent(m[1]);
    const body = await parseBody(req);
    const books = loadBooks();
    const book = books.find((b) => String(b.id) === String(id));
    if (!book) {
      send(res, 404, JSON.stringify({ error: "Not found" }), { "Content-Type": "application/json" });
      return;
    }
    if (body.status) book.status = body.status;
    if (body.title) book.title = body.title;
    if (body.author) book.author = body.author;
    if (body.notes) book.notes = body.notes;
    saveBooks(books);
    send(res, 200, JSON.stringify(book), { "Content-Type": "application/json" });
    return;
  }

  send(res, 404, layout("Not found", `<h2>404 Not found</h2><p>No route for ${escapeHtml(method)} ${escapeHtml(pathname)}</p><a href="/">Home</a>`), {
    "Content-Type": "text/html",
  });
}

const server = http.createServer(handler);

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  server.listen(PORT, () => {
    console.log(`Book tracker listening on http://localhost:${PORT}`);
  });
}

